import { VariantWithQuantity, VariantTableData } from '@/b2b-quick-order/types';

/**
 * Collects and transforms variant data with quantities into table data format
 * @param variants - Array of variants with quantities
 * @returns Array of collected variant data with optional optionsUIDs and parentSku
 */
export const collectVariantsData = (
  variants: VariantWithQuantity[]
): VariantTableData[] => {
  return variants
    .filter((v) => v.quantity > 0)
    .map((v) => {
      const baseData: VariantTableData = {
        sku: v.product.sku,
        name: v.product.name,
        inStock: v.product.inStock,
        attributes: v.product.attributes.reduce((acc, attr) => {
          if (attr.value) {
            acc[attr.name] = {
              label: attr.label,
              value: attr.value,
            };
          }
          return acc;
        }, {} as Record<string, { label: string; value: string | number }>),
        price: v.product.price.final.amount.value,
        quantity: v.quantity,
        subtotal: v.product.price.final.amount.value * v.quantity,
        image: v.product.images[0]?.url || '',
      };

      // Add optionsUIDs if selections are present (for configurable products)
      if (v.selections && v.selections.length > 0) {
        baseData.optionsUIDs = v.selections;
      }

      // Add parentSku if present (for configurable products)
      if (v.parentSku) {
        baseData.parentSku = v.parentSku;
      }

      return baseData;
    });
};
