import { OrderItem } from '@/b2b-quick-order/types';
import { buildCartItem } from './buildCartItem';

/**
 * Build cart items from forms for all order items
 * Only includes valid items (items with valid forms)
 */
export const buildCartItemsFromForms = (items: OrderItem[]) => {
  return items.map((item) => {
    const formId = item.id || item.sku;
    const form = document.forms[`form-${formId}` as any] as HTMLFormElement;
    if (!form) return null;

    const formData = new FormData(form);
    const isValid = formData.get('valid') === 'true';

    return isValid ? buildCartItem(formData) : null;
  });
};
