export interface BlurHandlerOptions {
  containerRef: HTMLElement | null;
  itemSelected: boolean;
  initialValue: string;
  currentValue: string;
  onValueRestore: (value: string) => void;
  onClose: () => void;
}

/**
 * Handles blur logic for search component
 * Checks if focus moved outside component and restores initial value if needed
 */
export const handleSearchBlur = (options: BlurHandlerOptions): void => {
  const {
    containerRef,
    itemSelected,
    initialValue,
    currentValue,
    onValueRestore,
    onClose,
  } = options;

  const activeElement = document.activeElement;
  const isWithinComponent = containerRef?.contains(activeElement);

  if (!isWithinComponent) {
    onClose();

    if (!itemSelected && initialValue !== currentValue) {
      onValueRestore(initialValue);
    }
  }
};

/**
 * Creates a blur handler with timeout
 */
export const createBlurHandler = (
  options: BlurHandlerOptions,
  delay: number = 150
): number => {
  return window.setTimeout(() => {
    handleSearchBlur(options);
  }, delay);
};

/**
 * Clears blur timeout if exists
 */
export const clearBlurTimeout = (timeoutRef: number | null): void => {
  if (timeoutRef) {
    clearTimeout(timeoutRef);
  }
};
