import { CSVValidationResult, SubmitSkuValue } from '@/b2b-quick-order/types';
import { cleanCsvValue } from './cleanCsvValue';

// Maximum number of rows allowed in CSV
const MAX_ROWS = 200;

export interface ValidationMessages {
  emptyFile: string;
  missingColumns: string;
  extraColumns: string;
  maxRowsExceeded: string;
  skuRequired: string;
  invalidQuantity: string;
  noValidData: string;
}

/**
 * Validates CSV content and extracts SKU/quantity data
 * Handles BOM, different line endings, quoted values, and empty lines
 * @param content - Raw CSV file content
 * @param messages - Localized error messages
 * @returns Validation result with data or error
 */
export const validateCsvContent = (
  content: string,
  messages: ValidationMessages
): CSVValidationResult => {
  // Remove BOM if present
  const cleanContent = content.replace(/^\uFEFF/, '');

  // Split by different line endings (handle \r\n, \n, \r)
  const lines = cleanContent.trim().split(/\r?\n|\r/);

  // Check if file is effectively empty after removing empty lines
  const hasContent = lines.some((line) => line.trim());
  if (!hasContent) {
    return { isValid: false, error: messages.emptyFile };
  }

  const header = lines[0]
    .split(',')
    .map((col) => cleanCsvValue(col).toLowerCase());
  const skuIndex = header.indexOf('sku');
  const qtyIndex = header.indexOf('qty');

  if (skuIndex === -1 || qtyIndex === -1) {
    return {
      isValid: false,
      error: messages.missingColumns,
    };
  }

  if (header.length !== 2) {
    return {
      isValid: false,
      error: messages.extraColumns,
    };
  }

  if (lines.length - 1 > MAX_ROWS) {
    return {
      isValid: false,
      error: messages.maxRowsExceeded.replace('{maxRows}', MAX_ROWS.toString()),
    };
  }

  const data: SubmitSkuValue = [];
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;

    const values = line.split(',').map((val) => cleanCsvValue(val));
    const sku = values[skuIndex];
    const qty = values[qtyIndex];

    if (!sku) {
      return {
        isValid: false,
        error: messages.skuRequired.replace('{rowNumber}', i.toString()),
      };
    }

    const quantity = parseInt(qty, 10);
    if (isNaN(quantity) || quantity <= 0 || !Number.isInteger(quantity)) {
      return {
        isValid: false,
        error: messages.invalidQuantity.replace('{rowNumber}', i.toString()),
      };
    }

    data.push({ sku, quantity });
  }

  if (data.length === 0) {
    return { isValid: false, error: messages.noValidData };
  }

  return { isValid: true, data };
};
