const STANDARD_FIELDS = [
  'sku',
  'parentSku',
  'itemId',
  'quantity',
  'optionsUIDs',
  'valid',
  'productType',
];

export interface ProcessedFormOptions {
  optionUIDs: string[];
  enteredOptions: { uid: string; value: string }[];
}

/**
 * Processes form data to extract product options
 * Separates base64-encoded configurable options (optionUIDs) from custom entered options
 */
export const processFormOptions = (
  formData: FormData
): ProcessedFormOptions => {
  const optionUIDs: string[] = [];
  const enteredOptions: { uid: string; value: string }[] = [];

  formData.forEach((value, key) => {
    if (STANDARD_FIELDS.includes(key)) return;

    const valueStr = value as string;
    // Check if this is an option UID (base64 encoded configurable option)
    if (valueStr && valueStr.match(/^[A-Za-z0-9+/=]+$/)) {
      optionUIDs.push(valueStr);
    } else {
      enteredOptions.push({ uid: key, value: valueStr });
    }
  });

  return { optionUIDs, enteredOptions };
};
