import {
  useCallback,
  useEffect,
  useMemo,
  useState,
  useRef,
} from 'preact/hooks';
import {
  SubmitSkuValue,
  UseQuickOrderMultipleSkuProps,
  UseQuickOrderMultipleSkuReturn,
} from '@/b2b-quick-order/types';
import { debounce } from '@adobe-commerce/elsie/lib/debounce';
import { events } from '@adobe-commerce/event-bus';

export const useQuickOrderMultipleSku = ({
  onChange,
}: UseQuickOrderMultipleSkuProps): UseQuickOrderMultipleSkuReturn => {
  const [textAreaValue, setTextAreaValue] = useState<string>('');
  const [loading, setLoading] = useState(false);
  // Store parsed SKU values without triggering re-renders (transient data for debounced callback)
  const textAreaValueRef = useRef<SubmitSkuValue>([]);
  // Track component mount status to prevent state updates after unmount
  const isMountedRef = useRef(true);

  useEffect(() => {
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  const modifySkuString = useCallback((value: string) => {
    const parsed = value
      .split(/[\s,]+/)
      .map((item) => item.trim())
      .filter((sku) => sku.length > 0);

    // Deduplicate: sum quantities for duplicate SKUs
    const skuMap = new Map<string, number>();
    parsed.forEach((sku) => {
      skuMap.set(sku, (skuMap.get(sku) || 0) + 1);
    });

    const result = Array.from(skuMap.entries()).map(([sku, quantity]) => ({
      sku,
      quantity,
    }));

    textAreaValueRef.current = result;

    return result;
  }, []);

  const debouncedOnChange = useMemo(
    () =>
      debounce((skus: string[]) => {
        if (onChange && isMountedRef.current) {
          onChange(skus);
        }
      }, 300),
    [onChange]
  );

  useEffect(() => {
    debouncedOnChange(modifySkuString(textAreaValue));
  }, [textAreaValue, debouncedOnChange, modifySkuString]);

  useEffect(() => {
    const loadingEvent = events.on(
      'quick-order/loading',
      (loading) => {
        if (isMountedRef.current) {
          setLoading(loading);
        }
      },
      {
        eager: true,
      }
    );
    return () => {
      loadingEvent?.off();
    };
  }, []);

  const handleChange = useCallback((e: Event) => {
    const target = e.target as HTMLTextAreaElement;
    const value = target.value;
    setTextAreaValue(value);
  }, []);

  const handleAddToList = useCallback(
    (additionalValues?: Array<{ sku: string; quantity: number }>) => {
      const textAreaSkus = textAreaValueRef.current;
      const allSkus = additionalValues
        ? [...textAreaSkus, ...additionalValues]
        : textAreaSkus;
      events.emit('quick-order/add-items', allSkus);
      setTextAreaValue('');
    },
    []
  );

  return {
    handleChange,
    textAreaValue,
    loading,
    handleAddToList,
  };
};
