import { OrderItem } from '@/b2b-quick-order/types';

/**
 * Validates order items to determine if all items are ready for cart addition
 * @param items - Array of order items to validate
 * @returns true if all items are valid, false otherwise
 */
export const validateOrderItems = (items: OrderItem[]): boolean => {
  if (items.length === 0) {
    return false;
  }

  return items.every((item) => {
    const hasBasicData = (item.urlKey || item.url) && item.name;
    if (!hasBasicData) {
      return false;
    }

    if (item.inStock === false) {
      return false;
    }

    if (item.options && item.options.length > 0) {
      const hasRequiredOptions = item.options.some((opt) => opt.required);

      if (hasRequiredOptions) {
        // Required options: all must be selected
        return item.options.every((opt) => {
          if (!opt.required) return true;
          return opt.items?.some((optItem) => optItem.selected);
        });
      }

      // Optional options: at least one must be selected
      const hasSelectedOption = item.options.some(
        (option) =>
          option.items &&
          option.items.length > 0 &&
          option.items.some((optionItem) => optionItem.selected === true)
      );
      return hasSelectedOption;
    }

    return true;
  });
};

/**
 * Get items that are out of stock
 * @param items - Array of order items to check
 * @returns Array of out of stock items with their names
 */
export const getOutOfStockItems = (
  items: OrderItem[]
): Array<{ sku: string; name: string }> => {
  return items
    .filter((item) => item.inStock === false)
    .map((item) => ({
      sku: item.sku,
      name: item.name,
    }));
};

/**
 * Get items with missing required options
 * @param items - Array of order items to check
 * @returns Array of items missing required options
 */
export const getItemsMissingOptions = (
  items: OrderItem[]
): Array<{ sku: string; name: string }> => {
  return items
    .filter((item) => {
      if (!item.options || item.options.length === 0) {
        return false;
      }
      const hasSelectedOption = item.options.some(
        (option) =>
          option.items &&
          option.items.length > 0 &&
          option.items.some((optionItem) => optionItem.selected === true)
      );
      return !hasSelectedOption;
    })
    .map((item) => ({
      sku: item.sku,
      name: item.name,
    }));
};

/**
 * Get items with incomplete data
 * @param items - Array of order items to check
 * @returns Array of items with incomplete data
 */
export const getItemsWithIncompleteData = (
  items: OrderItem[]
): Array<{ sku: string; name: string }> => {
  return items
    .filter((item) => {
      const hasBasicData = (item.urlKey || item.url) && item.name;
      return !hasBasicData;
    })
    .map((item) => ({
      sku: item.sku,
      name: item.name || 'Unknown',
    }));
};

/**
 * Get all items with validation errors
 * @param items - Array of order items to check
 * @returns Array of all items with validation errors and their SKUs
 */
export const getInvalidItems = (
  items: OrderItem[]
): Array<{ sku: string; name: string; reason: string }> => {
  const invalidItems: Array<{ sku: string; name: string; reason: string }> = [];

  items.forEach((item) => {
    const hasBasicData = (item.urlKey || item.url) && item.name;

    if (!hasBasicData) {
      invalidItems.push({
        sku: item.sku,
        name: item.name || 'Unknown',
        reason: 'incomplete_data',
      });
      return;
    }

    if (item.inStock === false) {
      invalidItems.push({
        sku: item.sku,
        name: item.name,
        reason: 'out_of_stock',
      });
      return;
    }

    if (item.options && item.options.length > 0) {
      const hasRequiredOptions = item.options.some((opt) => opt.required);

      if (hasRequiredOptions) {
        // Required options: all must be selected
        const allRequiredSelected = item.options.every((opt) => {
          if (!opt.required) return true;
          return opt.items?.some((optItem) => optItem.selected);
        });

        if (!allRequiredSelected) {
          invalidItems.push({
            sku: item.sku,
            name: item.name,
            reason: 'missing_required_options',
          });
        }
        return;
      }

      // Optional options: at least one must be selected
      const hasSelectedOption = item.options.some(
        (option) =>
          option.items &&
          option.items.length > 0 &&
          option.items.some((optionItem) => optionItem.selected === true)
      );
      if (!hasSelectedOption) {
        invalidItems.push({
          sku: item.sku,
          name: item.name,
          reason: 'missing_options',
        });
      }
    }
  });

  return invalidItems;
};
