import { FunctionComponent, memo } from 'preact/compat';
import { Button, CartList, Divider } from '@adobe-commerce/elsie/components';
import { classes } from '@adobe-commerce/elsie/lib/classes';
import { QuickOrderItemsListProps } from '@/b2b-quick-order/types';
import { Slot } from '@adobe-commerce/elsie/lib';
import { QuickOrderListItem, Search } from '@/b2b-quick-order/components';
import { useItemSearch } from '@/b2b-quick-order/hooks';
import '@/b2b-quick-order/components/QuickOrderItemsList/QuickOrderItemsList.css';

const QuickOrderItemsListComponent: FunctionComponent<
  QuickOrderItemsListProps
> = ({
  t,
  items,
  onRemove,
  clearItems,
  onUpdateQuantity,
  slots,
  handleAddToCart,
  isItemUpdating,
  loading,
  isDisabledButton,
  productsSearch,
  searchFilter,
}) => {
  const {
    searchValue,
    searchResults,
    handleSearchChange,
    shouldShowResults,
    handleItemClick,
  } = useItemSearch({
    productsSearch,
    initialSku: '',
    searchFilter,
  });

  return (
    <div
      className={classes(['b2b-quick-order-form-quick-order-items-list'])}
      role="region"
      aria-label={t.title}
    >
      <div className="b2b-quick-order-form-quick-order-items-list__title">
        {t.title}
      </div>

      {items.length > 0 && (
        <>
          <CartList
            role="list"
            className="b2b-quick-order-form-quick-order-items-list__list"
          >
            {items.map((item) => (
              <QuickOrderListItem
                key={item.id || item.sku}
                item={item}
                t={t}
                onRemove={onRemove}
                onUpdateQuantity={onUpdateQuantity}
                isUpdating={isItemUpdating?.(item.variantSku || item.sku)}
                loading={loading}
                productsSearch={productsSearch}
                searchFilter={searchFilter}
                slots={slots}
              />
            ))}
          </CartList>
          <Divider variant={'secondary'} />
        </>
      )}
      <div className="b2b-quick-order-form-quick-order-items-list__global-search">
        <Search
          t={t}
          onChange={handleSearchChange}
          items={searchResults}
          value={searchValue}
          shouldShowResults={shouldShowResults}
          onItemClick={handleItemClick}
          className="b2b-quick-order-form-quick-order-items-list__search"
        />
      </div>
      {items.length === 0 && (
        <div
          className="b2b-quick-order-form-quick-order-items-list__empty"
          data-testid="empty-items"
        >
          {t.emptyList}
        </div>
      )}
      <Slot
        slot={slots?.AddAllToCartButton}
        name="AddAllToCartButton"
        context={{
          handleAddToCart,
          clearItems,
          loading,
          isDisabledButton,
        }}
        data-testid="addAllToCart"
      >
        <div className="b2b-quick-order-form-quick-order-items-list__actions">
          <Button
            variant="primary"
            onClick={handleAddToCart}
            data-testid="add-all-to-cart-button"
            disabled={loading || isDisabledButton}
          >
            {t.addAllToCart}
          </Button>
        </div>
      </Slot>
    </div>
  );
};

export const QuickOrderItemsList = memo(QuickOrderItemsListComponent);
