import { OrderItem } from '@/b2b-quick-order/types';

/**
 * Merge duplicate items by removing the item at removeIndex and
 * adding its quantity to the item at mergeIntoIndex
 */
export const mergeDuplicateItems = (
  items: OrderItem[],
  removeIndex: number,
  mergeIntoIndex: number,
  quantityToAdd: number = 1
): OrderItem[] => {
  const removedItem = items[removeIndex];
  
  return items
    .map((item, index) => {
      if (index === mergeIntoIndex) {
        // Increase quantity of the duplicate and preserve parentSku
        return {
          ...item,
          quantity: item.quantity + quantityToAdd,
          // Preserve parentSku from either item
          parentSku: item.parentSku || removedItem?.parentSku,
        };
      } else if (index === removeIndex) {
        // Remove the item being merged
        return null;
      }
      return item;
    })
    .filter(Boolean) as OrderItem[];
};
