import { OrderItem, OrderItemInput } from '@/b2b-quick-order/types';
import { findDuplicateItem } from './findDuplicateItem';
import { generateItemId } from './generateItemId';

export interface ReplaceOrAddItemsResult {
  updatedItems: OrderItem[];
  addedItems: OrderItem[];
  replacedItems: OrderItem[];
  mergedItems: OrderItem[];
}

/**
 * Replace, merge, or add items into existing list
 * Handles three scenarios:
 * 1. Replace: When inputItem has replaceItemSku, replace item at same position
 *    - If new item already exists in list, collapse by removing replaced item and merging quantity
 * 2. Merge: When item exists, increase quantity
 * 3. Add: When item doesn't exist, add to end
 */
export const replaceOrAddItems = (
  existingItems: OrderItem[],
  newItems: OrderItem[],
  inputItems: OrderItemInput[]
): ReplaceOrAddItemsResult => {
  const updatedItems = [...existingItems];
  const addedItems: OrderItem[] = [];
  const replacedItems: OrderItem[] = [];
  const mergedItems: OrderItem[] = [];

  newItems.forEach((newItem, index) => {
    const inputItem = inputItems[index];

    // Scenario 1: Replace existing item at same position
    if (inputItem?.replaceItemSku) {
      const replaceIndex = updatedItems.findIndex(
        (item) =>
          item.sku === inputItem.replaceItemSku ||
          item.id === inputItem.replaceItemSku
      );

      if (replaceIndex !== -1) {
        // Check if new item already exists elsewhere in the list (collapse case)
        const existingIndex = findDuplicateItem(updatedItems, newItem);

        if (existingIndex !== -1 && existingIndex !== replaceIndex) {
          // Item already exists - remove replaced item and merge quantity into existing
          updatedItems.splice(replaceIndex, 1);
          // Adjust index if existing item was after the removed one
          const adjustedIndex =
            existingIndex > replaceIndex ? existingIndex - 1 : existingIndex;
          updatedItems[adjustedIndex] = {
            ...updatedItems[adjustedIndex],
            quantity: updatedItems[adjustedIndex].quantity + newItem.quantity,
            // Preserve parentSku from either item
            parentSku: updatedItems[adjustedIndex].parentSku || newItem.parentSku,
          };
          mergedItems.push(updatedItems[adjustedIndex]);
        } else {
          // Replace item at the same position
          const itemWithId = {
            ...newItem,
            id: generateItemId(newItem.sku),
          };
          updatedItems[replaceIndex] = itemWithId;
          replacedItems.push(itemWithId);
        }
        return;
      }
      // If item to replace not found, fall through to add logic
    }

    // Scenario 2 & 3: Merge or Add
    const existingIndex = findDuplicateItem(updatedItems, newItem);

    if (existingIndex !== -1) {
      // Item exists - merge by increasing quantity
      updatedItems[existingIndex] = {
        ...updatedItems[existingIndex],
        quantity: updatedItems[existingIndex].quantity + newItem.quantity,
        // Preserve parentSku from either item
        parentSku: updatedItems[existingIndex].parentSku || newItem.parentSku,
      };
      mergedItems.push(updatedItems[existingIndex]);
    } else {
      // Item doesn't exist - add new with unique ID
      const itemWithId = {
        ...newItem,
        id: generateItemId(newItem.sku),
      };
      updatedItems.push(itemWithId);
      addedItems.push(itemWithId);
    }
  });

  return { updatedItems, addedItems, replacedItems, mergedItems };
};
