import { FunctionComponent, memo, useMemo, useState } from 'preact/compat';
import {
  Table,
  Button,
  Price,
  Tag,
  Incrementer,
} from '@adobe-commerce/elsie/components';
import { classes } from '@adobe-commerce/elsie/lib/classes';
import {
  QuickOrderVariantsGridComponentProps,
  VariantRow,
} from '@/b2b-quick-order/types';
import { Slot } from '@adobe-commerce/elsie/lib';
import '@/b2b-quick-order/components/QuickOrderVariantsGrid/QuickOrderVariantsGrid.css';

const QuickOrderVariantsGridComponent: FunctionComponent<
  QuickOrderVariantsGridComponentProps
> = ({
  t,
  variants,
  loading = false,
  className,
  onQuantityChange,
  visibleVariantsLimit = 10,
  columns,
  slots,
}) => {
  const defaultColumns = useMemo(
    () => [
      { key: 'image', label: t.imageColumn || 'Image' },
      { key: 'sku', label: t.skuColumn || 'SKU' },
      { key: 'availability', label: t.availabilityColumn || 'Availability' },
      { key: 'price', label: t.priceColumn || 'Price' },
      { key: 'quantity', label: t.quantityColumn || 'Quantity' },
      { key: 'subtotal', label: t.subtotalColumn || 'Subtotal' },
    ],
    [t]
  );

  const tableColumns = columns || defaultColumns;

  const rowData = useMemo<VariantRow[]>(() => {
    return variants.map((variant, index) => {
      const { product, quantity } = variant;

      const priceValue = product.price.final.amount.value;
      const currency = product.price.final.amount.currency;

      const subtotal = priceValue * quantity;

      const availability = product.inStock
        ? t.inStock || 'In Stock'
        : t.outOfStock || 'Out of Stock';

      const row: VariantRow = {
        id: `${product.sku}-${index}`,
        image: (
          <Slot
            name="ImageCell"
            slot={slots?.ImageCell}
            context={{ variant, quantity, onQuantityChange }}
          >
            {product.images[0]?.url && (
              <img
                src={product.images[0].url}
                alt={product.name}
                className="b2b-quick-order-variants-grid__image"
              />
            )}
          </Slot>
        ),
        sku: (
          <Slot
            name="SKUCell"
            slot={slots?.SKUCell}
            context={{ variant, quantity, onQuantityChange }}
          >
            {product.sku}
          </Slot>
        ),
        availability: (
          <Slot
            name="AvailabilityCell"
            slot={slots?.AvailabilityCell}
            context={{ variant, quantity, onQuantityChange }}
          >
            <Tag
              label={availability}
              className={classes([
                'b2b-quick-order-variants-grid__availability',
                [
                  'b2b-quick-order-variants-grid__availability--in-stock',
                  product.inStock,
                ],
                [
                  'b2b-quick-order-variants-grid__availability--out-of-stock',
                  !product.inStock,
                ],
              ])}
            />
          </Slot>
        ),
        price: (
          <Slot
            name="PriceCell"
            slot={slots?.PriceCell}
            context={{ variant, quantity, onQuantityChange }}
          >
            <Price amount={priceValue} currency={currency} size="small" />
          </Slot>
        ),
        quantity: (
          <Slot
            name="QuantityCell"
            slot={slots?.QuantityCell}
            context={{ variant, quantity, onQuantityChange }}
          >
            <div data-testid={`variant-quantity-input-${index}`}>
              <Incrementer
                value={quantity}
                min={0}
                disabled={!product.inStock}
                onValue={(newQuantity: number) => {
                  onQuantityChange(product.sku, newQuantity);
                }}
                size="medium"
                className="b2b-quick-order-variants-grid__quantity-input"
                aria-label={`${t.quantityLabel || 'Quantity for'} ${
                  product.sku
                }`}
              />
            </div>
          </Slot>
        ),
        subtotal: (
          <Slot
            name="SubtotalCell"
            slot={slots?.SubtotalCell}
            context={{ variant, quantity, onQuantityChange }}
          >
            <Price amount={subtotal} currency={currency} size="small" />
          </Slot>
        ),
      };

      if (columns) {
        const standardKeys = [
          'image',
          'variant',
          'sku',
          'availability',
          'price',
          'quantity',
          'subtotal',
        ];
        columns.forEach((col) => {
          if (
            !standardKeys.includes(col.key) &&
            !Object.prototype.hasOwnProperty.call(row, col.key)
          ) {
            const slotName = `${
              col.key.charAt(0).toUpperCase() + col.key.slice(1)
            }Cell`;
            const slot = (slots as any)?.[slotName];
            if (slot) {
              row[col.key] = (
                <Slot
                  name={slotName}
                  slot={slot}
                  context={{ variant, quantity, onQuantityChange }}
                />
              );
            }
          }
        });
      }

      return row;
    });
  }, [variants, t, onQuantityChange, slots, columns]);

  const [isExpanded, setIsExpanded] = useState(false);
  const hasMoreItems = rowData.length > visibleVariantsLimit;
  const displayedRowData =
    hasMoreItems && !isExpanded
      ? rowData.slice(0, visibleVariantsLimit)
      : rowData;

  return (
    <div
      className={classes(['b2b-quick-order-variants-grid', className])}
      data-testid="variants-grid"
    >
      <Table
        columns={tableColumns}
        rowData={displayedRowData}
        loading={loading}
        mobileLayout="stacked"
        className="b2b-quick-order-variants-grid__table"
      />

      {hasMoreItems && (
        <div className="b2b-quick-order-variants-grid__footer">
          <Button
            variant="secondary"
            size="medium"
            onClick={() => setIsExpanded(!isExpanded)}
            className="b2b-quick-order-variants-grid__toggle-button"
          >
            {isExpanded
              ? `${t.showLess || 'Show Less'}`
              : `${t.showAll || 'Show All'} (${rowData.length})`}
          </Button>
        </div>
      )}
    </div>
  );
};

export const QuickOrderVariantsGrid = memo(QuickOrderVariantsGridComponent);
