import { OrderItem } from '@/b2b-quick-order/types';

/**
 * Get unique scope identifier for an item
 * Uses unique id if available, otherwise falls back to variantSku or sku
 */
export const getItemScope = (item: OrderItem): string => {
  const scopeKey = item.id || item.variantSku || item.sku;
  return `quick-order-item-${scopeKey}`;
};
