import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'preact/hooks';
import {
  VariantWithQuantity,
  ProductVariant,
  UseQuickOrderVariantsDataProps,
  UseQuickOrderVariantsDataReturn,
} from '@/b2b-quick-order/types';
import { debounce } from '@adobe-commerce/elsie/lib/debounce';
import { events } from '@adobe-commerce/event-bus';
import { collectVariantsData } from '@/b2b-quick-order/lib';

export const useQuickOrderVariantsData = ({
  initialVariants,
  onVariantsLoaded,
  onSelectedVariantsChange,
  debounceMs = 300,
  initialLoading = true,
}: UseQuickOrderVariantsDataProps = {}): UseQuickOrderVariantsDataReturn => {
  const [variants, setVariants] = useState<VariantWithQuantity[]>([]);
  const variantsRef = useRef<VariantWithQuantity[]>([]);
  const [loading, setLoading] = useState(initialLoading);
  const isClearingRef = useRef(false);
  const clearTimeoutRef = useRef<number | null>(null);

  // Emit event when initialVariants prop is provided (e.g., from Storybook)
  useEffect(() => {
    if (initialVariants && initialVariants.length > 0) {
      events.emit('quick-order/grid-ordering-variants', initialVariants);
    }
  }, [initialVariants]);

  // Initializing event
  useEffect(() => {
    const variantsEvent = events.on(
      'quick-order/grid-ordering-variants',
      (incomingVariants: ProductVariant[]) => {
        if (!incomingVariants || incomingVariants.length === 0) {
          setVariants([]);
          variantsRef.current = [];
          setLoading(false);
        } else {
          const variantsWithQuantity: VariantWithQuantity[] =
            incomingVariants.map((variant) => ({
              ...variant,
              quantity: 0,
            }));
          setVariants(variantsWithQuantity);
          variantsRef.current = variantsWithQuantity;
          setLoading(false);
          events.emit('quick-order/grid-ordering-selected-variants', []);
          onVariantsLoaded?.(variantsWithQuantity);
        }
      },
      {
        eager: true,
      }
    );

    return () => {
      variantsEvent?.off();
    };
  }, [onVariantsLoaded]);

  const debouncedSelectedVariantsChange = useMemo(
    () =>
      debounce((updatedVariants: VariantWithQuantity[]) => {
        const collectedData = collectVariantsData(updatedVariants);

        if (onSelectedVariantsChange) {
          onSelectedVariantsChange(collectedData);
        }
        events.emit(
          'quick-order/grid-ordering-selected-variants',
          collectedData
        );
      }, debounceMs),
    [onSelectedVariantsChange, debounceMs]
  );

  const updateQuantity = useCallback(
    (sku: string, quantity: number) => {
      // Block updateQuantity if clearing is in progress
      if (isClearingRef.current) {
        return;
      }

      setVariants((prevVariants) => {
        const updated = prevVariants.map((variant) => {
          if (variant.product.sku === sku) {
            if (!variant.product.inStock) {
              return { ...variant, quantity: 0 };
            }
            return { ...variant, quantity: Math.max(0, quantity) };
          }
          return variant;
        });

        variantsRef.current = updated;
        debouncedSelectedVariantsChange(updated);

        return updated;
      });
    },
    [debouncedSelectedVariantsChange]
  );

  const clearAllQuantities = useCallback(() => {
    // Clear previous timeout if exists
    if (clearTimeoutRef.current !== null) {
      clearTimeout(clearTimeoutRef.current);
    }

    isClearingRef.current = true;

    setVariants((prevVariants) => {
      const cleared = prevVariants.map((variant) => ({
        ...variant,
        quantity: 0,
      }));

      variantsRef.current = cleared;
      debouncedSelectedVariantsChange(cleared);
      return cleared;
    });

    // [USF-3838] Timeout required since an SDK Incrementer component using onBlur event timeout
    // We should ensure that a clear action will be executed after it
    clearTimeoutRef.current = window.setTimeout(() => {
      isClearingRef.current = false;
      clearTimeoutRef.current = null;
    }, 200);
  }, [debouncedSelectedVariantsChange]);

  useEffect(() => {
    const clearAllQuantitiesEvent = events.on(
      'quick-order/grid-ordering-reset-selected-variants',
      clearAllQuantities,
      {
        eager: true,
      }
    );

    return () => {
      clearAllQuantitiesEvent?.off();
    };
  }, [clearAllQuantities]);

  // Cleanup timeout on component unmount
  useEffect(() => {
    return () => {
      if (clearTimeoutRef.current !== null) {
        clearTimeout(clearTimeoutRef.current);
      }
    };
  }, []);

  const exportToCsv = useCallback(() => {
    const currentVariants =
      variantsRef.current.length > 0 ? variantsRef.current : variants;
    const variantsToExport = currentVariants.filter((v) => v.quantity > 0);

    if (variantsToExport.length === 0) {
      console.warn('No variants with quantity to export');
      return;
    }

    const csvHeader = 'SKU,Quantity\n';
    const csvRows = variantsToExport
      .map((v) => `${v.product.sku},${v.quantity}`)
      .join('\n');
    const csvContent = csvHeader + csvRows;

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);

    const timestamp = new Date().toISOString().split('T')[0];
    link.setAttribute('href', url);
    link.setAttribute('download', `product-variants-${timestamp}.csv`);
    link.style.visibility = 'hidden';

    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    URL.revokeObjectURL(url);
  }, [variants]);

  const collectTableData = useCallback(() => {
    const currentVariants =
      variantsRef.current.length > 0 ? variantsRef.current : variants;
    const tableData = currentVariants
      .filter((v) => v.quantity > 0)
      .map((variant) => ({
        sku: variant.product.sku,
        name: variant.product.name,
        inStock: variant.product.inStock,
        attributes: variant.product.attributes.reduce((acc, attr) => {
          if (attr.value && attr.value !== '') {
            acc[attr.name] = {
              label: attr.label,
              value: attr.value,
            };
          }
          return acc;
        }, {} as Record<string, { label: string; value: string | number }>),
        price: variant.product.price.final.amount.value,
        quantity: variant.quantity,
        subtotal: variant.product.price.final.amount.value * variant.quantity,
        image: variant.product.images[0]?.url || '',
      }));

    return tableData;
  }, [variants]);

  const variantsWithQuantity = useMemo(
    () => variants.filter((v) => v.quantity > 0).length,
    [variants]
  );

  return {
    variants,
    loading,
    updateQuantity,
    clearAllQuantities,
    exportToCsv,
    collectTableData,
    variantsWithQuantity,
  };
};
