import { FunctionComponent } from 'preact/compat';
import { AlertBanner } from '@adobe-commerce/elsie/components';
import { QuickOrderNotificationBannerProps } from '@/b2b-quick-order/types';
import '@/b2b-quick-order/components/QuickOrderNotificationBanner/QuickOrderNotificationBanner.css';
import { classes } from '@adobe-commerce/elsie/lib';

export const QuickOrderNotificationBanner: FunctionComponent<
  QuickOrderNotificationBannerProps
> = ({
  notification,
  onDismiss,
  onSkuClick,
  validationErrorText,
  backendErrorText,
  successText,
  partialSuccessText,
}) => {
  if (!notification) {
    return null;
  }

  const getMessage = () => {
    switch (notification.type) {
      case 'validation':
        return renderValidationMessage(
          validationErrorText,
          notification.clickableSkus,
          notification.details,
          onSkuClick
        );

      case 'partial-success':
        return renderPartialSuccessMessage(
          partialSuccessText,
          notification.message,
          notification.count,
          notification.clickableSkus,
          onSkuClick
        );

      case 'backend-error':
        return renderBackendErrorMessage(
          backendErrorText,
          notification.details
        );

      case 'success':
        return renderSuccessMessage(successText, notification.count);

      default:
        return <span>{notification.message}</span>;
    }
  };

  return (
    <div
      className={classes([
        'b2b-quick-order-notification-banner',
        [
          `b2b-quick-order-notification-banner--${notification.variant}`,
          notification.variant,
        ],
      ])}
    >
      <AlertBanner
        variant={notification.variant}
        message={getMessage()}
        onDismiss={onDismiss}
      />
    </div>
  );
};

function renderClickableSkus(
  skus: string[],
  onSkuClick: (sku: string) => void
) {
  return skus.map((sku, index) => (
    <span key={sku}>
      <a
        href="#"
        onClick={(e) => {
          e.preventDefault();
          onSkuClick(sku);
        }}
        style={{
          cursor: 'pointer',
          textDecoration: 'underline',
          color: 'white',
        }}
      >
        {sku}
      </a>
      {index < skus.length - 1 ? ', ' : ''}
    </span>
  ));
}

function renderValidationMessage(
  baseMessage: string,
  clickableSkus: string[] | undefined,
  details: string | undefined,
  onSkuClick?: (sku: string) => void
) {
  if (clickableSkus?.length && onSkuClick) {
    return (
      <span>
        {baseMessage} - {renderClickableSkus(clickableSkus, onSkuClick)}
      </span>
    );
  }

  return (
    <span>
      {baseMessage} - {details}
    </span>
  );
}

function renderPartialSuccessMessage(
  partialSuccessText: string | undefined,
  message: string,
  count: number | undefined,
  clickableSkus: string[] | undefined,
  onSkuClick?: (sku: string) => void
) {
  if (!partialSuccessText) {
    return <span>{message}</span>;
  }

  const partialMessage = partialSuccessText
    .replace('{count}', String(count || 0))
    .replace('{total}', String((count || 0) + (clickableSkus?.length || 0)));

  if (clickableSkus?.length && onSkuClick) {
    return (
      <span>
        {partialMessage}: {renderClickableSkus(clickableSkus, onSkuClick)}
      </span>
    );
  }

  return (
    <span>
      {partialMessage}: {clickableSkus?.join(', ') || 'Unknown'}
    </span>
  );
}

function renderBackendErrorMessage(
  backendErrorText: string,
  details: string | undefined
) {
  return (
    <span>
      {backendErrorText}
      {details ? ` - ${details}` : ''}
    </span>
  );
}

function renderSuccessMessage(successText: string, count: number | undefined) {
  if (count !== undefined) {
    return <span>{successText.replace('{count}', String(count))}</span>;
  }
  return <span>{successText}</span>;
}
