/**
 * Extract optionsUIDs from various data formats
 */
export const extractOptionsUIDs = (valuesData: any): string[] => {
  let optionsUIDs: string[] = [];

  if (valuesData && typeof valuesData === 'object') {
    if (valuesData.optionsUIDs && Array.isArray(valuesData.optionsUIDs)) {
      optionsUIDs = valuesData.optionsUIDs;
    } else if (Array.isArray(valuesData)) {
      optionsUIDs = valuesData;
    }
  } else if (typeof valuesData === 'string') {
    optionsUIDs = [valuesData];
  }

  return optionsUIDs;
};

/**
 * Get options from localStorage
 */
export const getOptionsFromStorage = (
  storageKey: string
): Record<string, string[]> => {
  try {
    const stored = localStorage.getItem(storageKey);
    if (stored) {
      return JSON.parse(stored);
    }
  } catch (e) {
    console.error('Error reading from localStorage:', e);
  }
  return {};
};

/**
 * Save options to localStorage
 */
export const saveOptionsToStorage = (
  storageKey: string,
  itemId: string,
  optionsUIDs: string[]
): void => {
  if (optionsUIDs.length === 0) {
    return;
  }

  try {
    const storageData = getOptionsFromStorage(storageKey);
    storageData[itemId] = optionsUIDs;
    localStorage.setItem(storageKey, JSON.stringify(storageData));
  } catch (e) {
    console.error('Error saving to localStorage:', e);
  }
};

/**
 * Remove options from localStorage for a specific item
 */
export const removeOptionsFromStorage = (
  storageKey: string,
  itemId: string
): void => {
  try {
    const storageData = getOptionsFromStorage(storageKey);
    delete storageData[itemId];
    localStorage.setItem(storageKey, JSON.stringify(storageData));
  } catch (e) {
    console.error('Error removing from localStorage:', e);
  }
};

/**
 * Enrich cart items with selected options from storage
 */
export const enrichCartItemsWithOptions = <T extends { sku: string; itemId?: string }>(
  cartItems: T[],
  items: Array<{ id?: string; sku: string; variantSku?: string; parentSku?: string }>,
  storageData: Record<string, string[]>
): Array<T & { optionsUIDs?: string[]; parentSku?: string }> => {
  return cartItems.map((cartItem) => {
    // First try to find by itemId (most reliable, doesn't change when variant changes)
    let item = cartItem.itemId 
      ? items.find((i) => (i.id || i.sku) === cartItem.itemId)
      : undefined;
    
    // Fallback to SKU matching if itemId not available or not found
    if (!item) {
      item = items.find((i) => {
        return cartItem.sku === i.sku || cartItem.sku === i.variantSku;
      });
    }

    if (item) {
      const itemId = item.id || item.sku;
      const selectedOptions = storageData[itemId];

      const enrichedItem: T & { optionsUIDs?: string[]; parentSku?: string } = {
        ...cartItem,
      };

      if (selectedOptions && selectedOptions.length > 0) {
        enrichedItem.optionsUIDs = selectedOptions;
      }

      // Always add parentSku if available
      if (item.parentSku) {
        enrichedItem.parentSku = item.parentSku;
      }

      return enrichedItem;
    }

    return cartItem;
  });
};
