import { OrderItem } from '@/b2b-quick-order/types';

/**
 * Find duplicate item in the list based on multiple comparison strategies
 * Returns the index of the duplicate item, or -1 if not found
 *
 * Strategies:
 * 1. Both have variantSku - compare variants
 * 2. Existing has variantSku, new has sku - compare them
 * 3. New has variantSku, existing has sku - compare them
 * 4. Neither has variantSku - compare base SKU
 */
export const findDuplicateItem = (
  items: OrderItem[],
  newItem: OrderItem
): number => {
  return items.findIndex((existing) => {
    // Strategy 1: Both have variantSku - compare variants
    if (newItem.variantSku && existing.variantSku) {
      return existing.variantSku === newItem.variantSku;
    }

    // Strategy 2: Existing has variantSku, new has sku - compare them
    // (e.g., existing configured product vs search result variant)
    if (existing.variantSku && !newItem.variantSku && newItem.sku) {
      return existing.variantSku === newItem.sku;
    }

    // Strategy 3: New has variantSku, existing has sku - compare them
    // (opposite of strategy 2)
    if (newItem.variantSku && !existing.variantSku && existing.sku) {
      return existing.sku === newItem.variantSku;
    }

    // Strategy 4: Neither has variantSku - compare base sku
    if (!newItem.variantSku && !existing.variantSku) {
      return existing.sku === newItem.sku;
    }

    return false;
  });
};

/**
 * Find duplicate item excluding a specific item by ID
 * Used when checking for duplicates after an item update
 */
export const findDuplicateItemExcluding = (
  items: OrderItem[],
  updatedItem: OrderItem,
  excludeItemId: string
): number => {
  return items.findIndex((existing) => {
    // Skip the item being updated
    if (existing.id === excludeItemId) return false;

    // Check if updatedItem's variantSku matches existing item
    if (updatedItem.variantSku && existing.variantSku) {
      return existing.variantSku === updatedItem.variantSku;
    }

    // Check if updatedItem's variantSku matches existing item's sku
    if (updatedItem.variantSku && !existing.variantSku && existing.sku) {
      return existing.sku === updatedItem.variantSku;
    }

    return false;
  });
};
