import { FunctionComponent, useMemo, useCallback, memo } from 'preact/compat';
import {
  CartItem,
  AccordionSection,
  PriceRange,
} from '@adobe-commerce/elsie/components';
import { Slot } from '@adobe-commerce/elsie/lib';
import { QuickOrderListItemProps } from '@/b2b-quick-order/types';
import { useItemSearch } from '@/b2b-quick-order/hooks';
import '@/b2b-quick-order/components/QuickOrderListItem/QuickOrderListItem.css';
import { Search } from '@/b2b-quick-order/components';

const QuickOrderListItemComponent: FunctionComponent<
  QuickOrderListItemProps
> = ({
  item,
  t,
  onRemove,
  onUpdateQuantity,
  isUpdating,
  loading,
  productsSearch,
  searchFilter,
  slots,
}) => {
  // Generate unique scope identifier Dropins - use item.id if available to distinguish multiple items with same sku
  const scope = `quick-order-item-${item.id || item.variantSku || item.sku}`;
  const currentSku = item?.variantSku ?? item?.sku;

  const {
    searchValue,
    searchResults,
    handleSearchChange,
    shouldShowResults,
    handleItemClick,
  } = useItemSearch({
    productsSearch,
    initialSku: currentSku,
    replaceItemSku: item.sku,
    searchFilter,
  });

  const formName = `form-${item.id || currentSku}`;
  const isValid = item.inStock && item.addToCartAllowed;
  const hasOptions = item.options && item.options.length > 0;

  const hasRequiredOptions = useMemo(
    () => hasOptions && item.options.some((option) => option.required),
    [hasOptions, item.options]
  );

  // Check if all required options are selected
  const allRequiredOptionsSelected = useMemo(() => {
    if (!hasOptions) return true;

    if (hasRequiredOptions) {
      // If there are required options, check that all required ones are selected
      // (optional options can be left unselected)
      return item.options.every((option) => {
        if (!option.required) return true; // Skip optional options
        return (
          option.items && option.items.some((optionItem) => optionItem.selected)
        );
      });
    }

    // If NO required options, ALL options must be selected to close accordion
    return item.options.every((option) => {
      return (
        option.items && option.items.some((optionItem) => optionItem.selected)
      );
    });
  }, [hasOptions, hasRequiredOptions, item.options]);

  const mainImage = useMemo(
    () => item.images?.find((img) => img.roles?.includes('image')),
    [item.images]
  );

  // Memoize handlers
  const handleRemove = useCallback(() => {
    // Use item.id if available, otherwise fall back to sku
    onRemove?.(item.id || item.sku);
  }, [onRemove, item.id, item.sku]);

  const handleQuantityChange = useCallback(
    (newQty: number) => {
      onUpdateQuantity?.(currentSku, newQty);
      // Update hidden quantity field
      const form = document.forms[formName as any] as HTMLFormElement;
      if (form) {
        const qtyInput = form.querySelector(
          'input[name="quantity"]'
        ) as HTMLInputElement;
        if (qtyInput) qtyInput.value = String(newQty);
      }
    },
    [onUpdateQuantity, currentSku, formName]
  );

  const searchSlot = (
    <Slot
      name="QuickOrderItemSearch"
      slot={slots?.QuickOrderItemSearch}
      context={{
        item,
        scope,
        handleSearchChange,
        searchResults,
        searchValue,
        shouldShowResults,
        handleItemClick,
      }}
    >
      <Search
        t={t}
        onChange={handleSearchChange}
        items={searchResults}
        value={searchValue}
        shouldShowResults={shouldShowResults}
        className="b2b-quick-order-form-quick-order-items__item-search"
        onItemClick={handleItemClick}
        slots={slots}
      />
    </Slot>
  );

  if (!item.name && !item.images?.length) {
    return (
      <form
        key={item.sku}
        name={formName}
        className="b2b-quick-order-form-quick-order-items__item-form"
        onSubmit={(e) => e.preventDefault()}
        data-sku={item.sku}
      >
        <input type="hidden" name="sku" value={item.sku} />
        <input type="hidden" name="quantity" value={item.quantity} />
        <input type="hidden" name="valid" value="false" />
        <input type="hidden" name="productType" value="" />
        {item.parentSku && <input type="hidden" name="parentSku" value={item.parentSku} />}
        {searchSlot}

        <CartItem
          sku={<span>{item.sku}</span>}
          title={<span>{t.productNotFound}</span>}
          quantity={item.quantity}
          alert={
            <div className="b2b-quick-order-items__error">
              {t.productNotFoundDescription?.replace('{sku}', item.sku)}
            </div>
          }
          disabled={loading}
          onRemove={handleRemove}
          ariaLabel={`${t.productNotFound} - ${item.sku}`}
        />
      </form>
    );
  }

  return (
    <form
      key={currentSku}
      name={formName}
      className="b2b-quick-order-form-quick-order-items__item-form"
      onSubmit={(e) => e.preventDefault()}
      data-sku={currentSku}
    >
      <input type="hidden" name="sku" value={currentSku} />
      <input type="hidden" name="quantity" value={item.quantity} />
      <input type="hidden" name="valid" value={isValid ? 'true' : 'false'} />
      <input type="hidden" name="productType" value={item.productType || ''} />
      {item.id && <input type="hidden" name="itemId" value={item.id} />}
      {item.parentSku && <input type="hidden" name="parentSku" value={item.parentSku} />}
      {searchSlot}
      <CartItem
        title={<span>{item.name}</span>}
        sku={<span>{currentSku}</span>}
        image={
          mainImage ? (
            <img src={mainImage.url} alt={mainImage.label || item.name} />
          ) : undefined
        }
        price={
          <Slot
            name="ProductPrice"
            slot={slots?.ProductPrice}
            context={{
              item,
              scope,
            }}
          >
            <PriceRange
              minimumAmount={item.prices.final.minimumAmount}
              maximumAmount={item.prices.final.maximumAmount}
              amount={item.prices.final.amount}
              currency={item.prices.final.currency}
            />
          </Slot>
        }
        quantity={item.quantity}
        alert={
          item.inStock === false ? (
            <div className="b2b-quick-order-items__alert">{t.outOfStock}</div>
          ) : undefined
        }
        warning={
          hasOptions && !allRequiredOptionsSelected ? (
            <div className="b2b-quick-order-items__warning">
              {t.configurableOptionsWarning}
            </div>
          ) : undefined
        }
        footer={
          hasOptions ? (
            <AccordionSection
              title={t.productOptions}
              ariaLabelTitle={t.productOptions}
              defaultOpen={!allRequiredOptionsSelected}
              className="b2b-quick-order-list-item__accordion"
              actionIconPosition="left"
            >
              <Slot
                name="ProductOptions"
                slot={slots?.ProductOptions}
                context={{
                  item,
                  scope,
                }}
              >
                <div className="b2b-quick-order-items__configurable-error">
                  {t.configurableProductErrorDescription}
                </div>
              </Slot>
            </AccordionSection>
          ) : undefined
        }
        updating={isUpdating}
        disabled={loading}
        loading={loading}
        onRemove={handleRemove}
        onQuantity={handleQuantityChange}
        ariaLabel={`${item.name} - ${item.sku}`}
      />
    </form>
  );
};

export const QuickOrderListItem = memo(QuickOrderListItemComponent);
