import { processFormOptions } from './processFormOptions';

export interface CartItem {
  sku: string;
  quantity: number;
  itemId?: string;
  parentSku?: string;
  optionsUIDs?: string[];
  enteredOptions?: { uid: string; value: string }[];
}

/**
 * Builds a cart item object from form data
 * Extracts SKU, quantity, parent SKU, and product options
 */
export const buildCartItem = (formData: FormData): CartItem => {
  const quantityValue = Number(formData.get('quantity'));
  const quantity = !quantityValue || quantityValue < 1 ? 1 : quantityValue;

  const cartItem: CartItem = {
    sku: formData.get('sku') as string,
    quantity,
  };

  const itemId = formData.get('itemId');
  if (itemId) {
    cartItem.itemId = itemId as string;
  }

  const parentSku = formData.get('parentSku');
  if (parentSku) {
    cartItem.parentSku = parentSku as string;
  }

  const { optionUIDs, enteredOptions } = processFormOptions(formData);

  if (optionUIDs.length > 0) {
    cartItem.optionsUIDs = optionUIDs;
  }

  if (enteredOptions.length > 0) {
    cartItem.enteredOptions = enteredOptions;
  }

  return cartItem;
};
