import { useCallback, useEffect, useRef, useState } from 'preact/hooks';
import {
  OrderItemInput,
  OrderItem,
  UseQuickOrderItemsProps,
  UseQuickOrderItemsReturn,
} from '@/b2b-quick-order/types';
import { events } from '@adobe-commerce/event-bus';
import { useText } from '@adobe-commerce/elsie/i18n';
import {
  mapProductsToOrderItems,
  validateOrderItems,
  getItemScope,
  replaceOrAddItems,
  updateItemInList,
  buildCartItemsFromForms,
  extractOptionsUIDs,
  saveOptionsToStorage,
  getOptionsFromStorage,
  enrichCartItemsWithOptions,
  getInvalidItems,
  isItemInvalid,
} from '@/b2b-quick-order/lib';

export const useQuickOrderItems = ({
  getProductsData,
  handleAddToCart,
}: UseQuickOrderItemsProps = {}): UseQuickOrderItemsReturn => {
  const [items, setItems] = useState<OrderItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [updatingItems, setUpdatingItems] = useState<Set<string>>(new Set());
  const [isDisabledButton, setIsDisabledButton] = useState(false);
  const [notification, setNotification] = useState<{
    type: 'validation' | 'partial-success' | 'success' | 'backend-error';
    variant: 'success' | 'warning' | 'neutral' | 'brand';
    message: string;
    details?: string;
    count?: number;
    clickableSkus?: string[];
  } | null>(null);
  const [attemptedSkus, setAttemptedSkus] = useState<string[]>([]);
  const attemptedSkusRef = useRef<string[]>([]);

  const t = useText({
    validationError: 'QuickOrder.QuickOrderItem.notification.validationError',
    backendError: 'QuickOrder.QuickOrderItem.notification.backendError',
    success: 'QuickOrder.QuickOrderItem.notification.success',
    partialSuccess: 'QuickOrder.QuickOrderItem.notification.partialSuccess',
    unexpectedError: 'QuickOrder.QuickOrderItem.notification.unexpectedError',
  });

  const STORAGE_KEY = 'quick-order-selected-options';

  const dismissNotification = useCallback(() => {
    setNotification(null);
  }, []);

  const setDisabledCartButton = useCallback((disabled: boolean) => {
    setIsDisabledButton(disabled);
  }, []);

  useEffect(() => {
    const loadingEvent = events.on(
      'quick-order/loading',
      (loadingState) => {
        setLoading(loadingState);
      },
      {
        eager: true,
      }
    );
    return () => {
      loadingEvent?.off();
    };
  }, []);

  useEffect(() => {
    const itemsEvent = events.on(
      'quick-order/add-items',
      async (eventPayload: OrderItemInput[]) => {
        if (eventPayload && eventPayload.length > 0) {
          if (!getProductsData) {
            return;
          }

          setLoading(true);
          events.emit('quick-order/loading', true);
          const requestedSkus = eventPayload
            .map((item) => item.variantSku || item.sku)
            .filter(Boolean);
          setUpdatingItems(
            (prev) => new Set([...Array.from(prev), ...requestedSkus])
          );

          try {
            let newItems: OrderItem[] = [];
            try {
              const fetchedProducts =
                (await getProductsData(eventPayload)) ?? [];
              setDisabledCartButton(
                eventPayload.length !== fetchedProducts.length
              );
              newItems = mapProductsToOrderItems(eventPayload, fetchedProducts);
            } catch (error) {
              console.error('Error fetching products data:', error);
              newItems = mapProductsToOrderItems(eventPayload, []);
            }

            const invalidNewItems = getInvalidItems(newItems);
            if (invalidNewItems.length > 0) {
              const invalidSkus = invalidNewItems.map((item) => item.sku);
              setNotification((prev) => {
                if (prev?.type === 'validation' && prev.clickableSkus) {
                  // Merge with existing validation SKUs
                  const mergedSkus = [
                    ...new Set([...prev.clickableSkus, ...invalidSkus]),
                  ];
                  return {
                    ...prev,
                    clickableSkus: mergedSkus,
                  };
                }
                return {
                  type: 'validation',
                  variant: 'warning',
                  message: t.validationError,
                  clickableSkus: invalidSkus,
                };
              });
            }

            setItems((prevItems) => {
              const { updatedItems, addedItems, mergedItems, replacedItems } =
                replaceOrAddItems(prevItems, newItems, eventPayload);

              replacedItems.forEach((item) => {
                const scope = getItemScope(item);
                events.emit(`${scope}/pdp/data`, item);
              });

              mergedItems.forEach((item) => {
                const scope = getItemScope(item);
                events.emit(`${scope}/pdp/data`, item);
              });

              addedItems.forEach((item) => {
                const scope = getItemScope(item);
                events.emit(`${scope}/pdp/data`, item);
              });

              return updatedItems;
            });
          } finally {
            setLoading(false);
            events.emit('quick-order/loading', false);
            setUpdatingItems(
              (prev) =>
                new Set(
                  Array.from(prev).filter((sku) => !requestedSkus.includes(sku))
                )
            );
          }
        }
      },
      {
        eager: true,
      }
    );

    return () => {
      itemsEvent?.off();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [getProductsData, setDisabledCartButton]);

  useEffect(() => {
    const scopesList = items.map((item) => {
      const scope = getItemScope(item);
      const itemId = item.id; // Capture the specific item's ID for this listener

      return events.on(`${scope}/pdp/data`, (updatedItem: OrderItem) => {
        setItems((prevItems) => {
          const result = updateItemInList(
            prevItems,
            itemId || '',
            updatedItem,
            item.quantity || 1
          );
          return result.updatedItems;
        });
      });
    });

    return () => {
      scopesList?.forEach((scope) => {
        scope?.off();
      });
    };
  }, [items, STORAGE_KEY]);

  useEffect(() => {
    const isValid = validateOrderItems(items);
    setDisabledCartButton(!isValid);
  }, [items, setDisabledCartButton]);

  useEffect(() => {
    setNotification((prev) => {
      // Only process notifications with clickable SKUs
      if (!prev || !prev.clickableSkus || prev.clickableSkus.length === 0) {
        return prev;
      }

      const stillInvalidSkus = prev.clickableSkus.filter((sku) => {
        // Find ALL items with this SKU (could be multiple for configurable products)
        const matchingItems = items.filter(
          (i) => i.sku === sku || i.variantSku === sku
        );
        if (matchingItems.length === 0) return false; // Item removed

        // Keep SKU in notification if ANY matching item is invalid
        return matchingItems.some((item) => isItemInvalid(item));
      });

      // Clear notification only if all SKUs are valid
      if (stillInvalidSkus.length === 0) {
        return null;
      }

      // Update notification if SKUs changed
      if (stillInvalidSkus.length !== prev.clickableSkus.length) {
        return {
          ...prev,
          clickableSkus: stillInvalidSkus,
        };
      }

      return prev;
    });
  }, [items]);

  useEffect(() => {
    // If Add to Cart button is disabled and there are items,
    // but no validation notification is shown - display it
    if (!isDisabledButton || items.length === 0) {
      return;
    }

    setNotification((prev) => {
      // Don't override existing validation/partial-success notifications
      if (
        prev &&
        (prev.type === 'validation' || prev.type === 'partial-success')
      ) {
        return prev;
      }

      const invalidItems = getInvalidItems(items);
      if (invalidItems.length === 0) {
        return prev;
      }

      const invalidSkus = [...new Set(invalidItems.map((item) => item.sku))];

      // Only set notification if it doesn't already have the same SKUs
      const existingSkus = prev?.clickableSkus || [];
      const hasChanges =
        invalidSkus.length !== existingSkus.length ||
        !invalidSkus.every((sku) => existingSkus.includes(sku));

      if (hasChanges) {
        return {
          type: 'validation',
          variant: 'warning',
          message: t.validationError,
          clickableSkus: invalidSkus,
        };
      }

      return prev;
    });
  }, [isDisabledButton, items, t.validationError]);

  useEffect(() => {
    const eventsList = items.map((item) => {
      const scope = getItemScope(item);
      const itemId = item.id || item.sku;

      return events.on(`${scope}/pdp/values`, (valuesData: any) => {
        const optionsUIDs = extractOptionsUIDs(valuesData);
        saveOptionsToStorage(STORAGE_KEY, itemId, optionsUIDs);
      });
    });

    return () => {
      eventsList.forEach((event) => {
        event?.off();
      });
    };
  }, [items, STORAGE_KEY]);

  useEffect(() => {
    attemptedSkusRef.current = attemptedSkus;
  }, [attemptedSkus]);

  useEffect(() => {
    const successEvent = events.on('cart/product/added', (products: any[]) => {
      const addedCount = Array.isArray(products) ? products.length : 0;
      const addedSkus = Array.isArray(products)
        ? products.map((p: any) => p.sku).filter(Boolean)
        : [];

      if (attemptedSkusRef.current.length > 0) {
        // Count occurrences of each SKU in attempted and added arrays
        const attemptedSkuCounts = attemptedSkusRef.current.reduce((acc, sku) => {
          acc[sku] = (acc[sku] || 0) + 1;
          return acc;
        }, {} as Record<string, number>);

        const addedSkuCounts = addedSkus.reduce((acc, sku) => {
          acc[sku] = (acc[sku] || 0) + 1;
          return acc;
        }, {} as Record<string, number>);

        // Find SKUs that weren't fully added (attempted count > added count)
        const failedSkus: string[] = [];
        Object.keys(attemptedSkuCounts).forEach((sku) => {
          const attempted = attemptedSkuCounts[sku];
          const added = addedSkuCounts[sku] || 0;
          const failedCount = attempted - added;
          
          // Add the SKU to failedSkus for each failed attempt
          for (let i = 0; i < failedCount; i++) {
            failedSkus.push(sku);
          }
        });

        if (failedSkus.length > 0 && addedCount > 0) {
          setNotification({
            type: 'partial-success',
            variant: 'warning',
            message: t.partialSuccess,
            count: addedCount,
            clickableSkus: failedSkus,
          });
          setAttemptedSkus([]);
        }
      } else {
        // No tracking context - ignore event
        return;
      }
    });

    const errorEvent = events.on(
      'quick-order/add-to-cart-error',
      (error: { message: string }) => {
        setNotification({
          type: 'backend-error',
          variant: 'warning',
          message: t.backendError,
          details: error.message,
        });
        setAttemptedSkus([]);
      }
    );

    return () => {
      successEvent?.off();
      errorEvent?.off();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [attemptedSkus]);

  useEffect(() => {
    const cartDataEvent = events.on(
      'cart/data',
      (cartData: any) => {
        if (
          attemptedSkusRef.current.length === 0 ||
          !cartData?.items ||
          cartData.items.length === 0
        ) {
          return;
        }

        // For configurable products, check both variant SKU and parent SKU
        const cartSkus = cartData.items.flatMap((item: any) => {
          const skus = [];
          if (item.sku) skus.push(item.sku);
          if (item.product?.sku) skus.push(item.product.sku);
          return skus;
        });

        const addedSkus = attemptedSkusRef.current.filter((sku) =>
          cartSkus.includes(sku)
        );

        if (addedSkus.length === 0) {
          return;
        }

        setNotification({
          type: 'success',
          variant: 'success',
          message: t.success,
          count: addedSkus.length,
        });

        setAttemptedSkus([]);
        events.emit('quick-order/loading', false);
      },
      {
        eager: true,
      }
    );

    return () => {
      cartDataEvent?.off();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const removeItem = useCallback((identifier: string) => {
    setItems((prevItems) =>
      prevItems.filter(
        (item) => item.id !== identifier && item.sku !== identifier
      )
    );
  }, []);

  const clearItems = useCallback(() => {
    setItems([]);
    setNotification(null);
  }, []);

  const updateItemQuantity = useCallback((sku: string, quantity: number) => {
    setItems((prevItems) =>
      prevItems.map((item) => {
        const itemCurrentSku = item.variantSku || item.sku;
        return itemCurrentSku === sku ? { ...item, quantity } : item;
      })
    );
  }, []);

  const isItemUpdating = useCallback(
    (sku: string) => {
      return updatingItems.has(sku);
    },
    [updatingItems]
  );

  const addToCart = useCallback(() => {
    const cartItems = buildCartItemsFromForms(items).filter(
      (item): item is NonNullable<typeof item> => item !== null
    );

    if (items.length > 0) {
      const isValid = validateOrderItems(items);

      if (!isValid) {
        const invalidItems = getInvalidItems(items);
        const invalidSkus = invalidItems.map((item) => item.sku);

        setNotification({
          type: 'validation',
          variant: 'warning',
          message: t.validationError,
          clickableSkus: invalidSkus,
        });
        return;
      }
    }

    if (cartItems.length === 0) {
      // Only show validation error if we have items in state
      if (items.length > 0) {
        const invalidItems = getInvalidItems(items);
        const invalidSkus = invalidItems.map((item) => item.sku);

        setNotification({
          type: 'validation',
          variant: 'warning',
          message: t.validationError,
          clickableSkus: invalidSkus,
        });
      }
      return;
    }

    setNotification(null);

    // Track SKUs with their count to handle duplicate SKUs correctly
    const skusToAdd = cartItems
      .map((item) => item.sku)
      .filter((sku): sku is string => Boolean(sku));
    setAttemptedSkus(skusToAdd);

    const storageData = getOptionsFromStorage(STORAGE_KEY);
    const enrichedCartItems = enrichCartItemsWithOptions(
      cartItems,
      items,
      storageData
    );

    if (handleAddToCart) {
      events.emit('quick-order/loading', true);
      Promise.resolve(handleAddToCart(enrichedCartItems, clearItems))
        .then((errorMessage) => {
          if (errorMessage && typeof errorMessage === 'string') {
            setNotification({
              type: 'backend-error',
              variant: 'warning',
              message: t.backendError,
              details: errorMessage,
            });
            setAttemptedSkus([]);
          } else {
            // Success - clear attempted SKUs to prevent false warnings from cart/product/added event
            setAttemptedSkus([]);
          }
        })
        .catch((error) => {
          setNotification({
            type: 'backend-error',
            variant: 'warning',
            message: t.backendError,
            details: error.message || t.unexpectedError,
          });
          setAttemptedSkus([]);
        })
        .finally(() => {
          events.emit('quick-order/loading', false); // Emit loading event after add to cart process completes
        });
    } else {
      events.emit('quick-order/add-to-cart', enrichedCartItems);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [items, handleAddToCart, STORAGE_KEY]);

  return {
    items,
    loading,
    removeItem,
    clearItems,
    updateItemQuantity,
    addToCart,
    isItemUpdating,
    isDisabledButton,
    setDisabledCartButton,
    notification,
    dismissNotification,
  };
};
