import { OrderItem, OrderItemInput } from '@/b2b-quick-order/types';
import { DEFAULT_QUICK_ORDER_ITEM } from '@/b2b-quick-order/configs';

/**
 * Maps fetched products to OrderItems
 * Creates error items for products not found in the response
 * @param requestedItems - Items that were requested
 * @param products - Products returned from API
 * @returns Array of OrderItems with proper quantity set
 */
export const mapProductsToOrderItems = (
  requestedItems: OrderItemInput[],
  products: OrderItem[]
): OrderItem[] => {
  // Handle empty or undefined products array
  if (!products || !Array.isArray(products)) {
    return requestedItems.map((requestedItem) => ({
      ...DEFAULT_QUICK_ORDER_ITEM,
      sku: requestedItem.sku,
      quantity: requestedItem.quantity ?? 1,
    })) as OrderItem[];
  }

  return requestedItems.map((requestedItem) => {
    const foundProduct = products.find((p) => p?.sku === requestedItem?.sku);

    if (foundProduct) {
      // Check if this is a configurable product variant
      const hasVariant = requestedItem.variantSku || foundProduct.variantSku;
      
      return {
        ...foundProduct,
        ...(hasVariant && {
          variantSku: requestedItem.variantSku || foundProduct.variantSku,
          // Store parent SKU when product has a variant
          parentSku: foundProduct.sku,
        }),
        quantity: requestedItem.quantity ?? 1,
      };
    }

    // Product not found - create error item
    return {
      ...DEFAULT_QUICK_ORDER_ITEM,
      sku: requestedItem.sku,
      ...(requestedItem.variantSku && { 
        variantSku: requestedItem.variantSku,
        parentSku: requestedItem.sku,
      }),
      quantity: requestedItem.quantity ?? 1,
    } as OrderItem;
  });
};
