import { FunctionComponent } from 'preact/compat';
import { QuickOrderDisabledOverlayProps } from '@/b2b-quick-order/types';
import '@/b2b-quick-order/components/QuickOrderDisabledOverlay/QuickOrderDisabledOverlay.css';

export const QuickOrderDisabledOverlay: FunctionComponent<
  QuickOrderDisabledOverlayProps
> = ({ isDisabled, message, children }) => {
  return (
    <div className="b2b-quick-order-disabled-overlay">
      <div
        className="b2b-quick-order-disabled-overlay__content"
        style={{ pointerEvents: isDisabled ? 'none' : 'auto' }}
      >
        {children}
      </div>
      {isDisabled && (
        <>
          <div className="b2b-quick-order-disabled-overlay__blur" />
          <div className="b2b-quick-order-disabled-overlay__message">
            {message}
          </div>
        </>
      )}
    </div>
  );
};
