import {
  useCallback,
  useState,
  useMemo,
  useRef,
  useEffect,
} from 'preact/hooks';
import { debounce } from '@adobe-commerce/elsie/lib/debounce';
import { OrderItem, UseItemSearchProps } from '@/b2b-quick-order/types';
import { events } from '@adobe-commerce/event-bus';
import { SEARCH_FILTER } from '@/b2b-quick-order/configs';

export const useItemSearch = ({
  productsSearch,
  initialSku,
  replaceItemSku,
  searchFilter = SEARCH_FILTER,
}: UseItemSearchProps) => {
  const [searchValue, setSearchValue] = useState(initialSku);
  const [searchResults, setSearchResults] = useState<OrderItem[]>([]);
  const [isTouched, setIsTouched] = useState(false);

  // Track if component is mounted to prevent state updates after unmount
  const isMountedRef = useRef(true);

  useEffect(() => {
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  // Update search value when initialSku changes (e.g., after merge)
  useEffect(() => {
    if (!isTouched) {
      setSearchValue(initialSku);
    }
  }, [initialSku, isTouched]);

  const debouncedSearch = useMemo(
    () =>
      debounce(async (searchTerm: string) => {
        if (!searchTerm || !productsSearch) {
          if (isMountedRef.current) {
            setSearchResults([]);
          }
          return;
        }

        try {
          const result = await productsSearch({
            phrase: searchTerm,
            filter: searchFilter,
          });
          if (isMountedRef.current) {
            setSearchResults(result.items || []);
          }
        } catch (error) {
          console.error('Error searching products:', error);
          if (isMountedRef.current) {
            setSearchResults([]);
          }
        }
      }, 300),
    [productsSearch, searchFilter]
  );

  const handleSearchChange = useCallback(
    (e: Event) => {
      const target = e.target as HTMLInputElement;
      const value = target.value;
      setSearchValue(value);
      setIsTouched(true);
      debouncedSearch(value);
    },
    [debouncedSearch]
  );

  const resetSearch = useCallback(() => {
    setSearchValue('');
    setSearchResults([]);
    setIsTouched(false);
  }, []);

  const handleItemClick = useCallback(
    (clickedItem: OrderItem) => {
      // Build item data for emission
      // Just send the data as-is from the search result
      // The deduplication logic will handle matching correctly
      const itemData = {
        sku: clickedItem.sku,
        ...(clickedItem.variantSku && { variantSku: clickedItem.variantSku }),
        quantity: 1,
        ...(replaceItemSku && { replaceItemSku }),
      };

      events.emit('quick-order/add-items', [itemData]);
      resetSearch();
    },
    [replaceItemSku, resetSearch]
  );

  return {
    searchValue,
    searchResults,
    handleSearchChange,
    shouldShowResults: isTouched,
    resetSearch,
    handleItemClick,
  };
};
