import { OrderItem } from '@/b2b-quick-order/types';
import { findDuplicateItemExcluding } from './findDuplicateItem';
import { mergeDuplicateItems } from './mergeDuplicateItems';

export interface UpdateItemResult {
  updatedItems: OrderItem[];
  wasMerged: boolean;
  mergedIntoIndex?: number;
}

/**
 * Update a specific item in the list and check for duplicates
 * If duplicate is found, merge the items
 */
export const updateItemInList = (
  items: OrderItem[],
  itemId: string,
  updatedItem: OrderItem,
  currentQuantity: number = 1
): UpdateItemResult => {
  // Check if the updated item's variantSku matches another existing item
  const duplicateIndex = itemId
    ? findDuplicateItemExcluding(items, updatedItem, itemId)
    : -1;

  if (duplicateIndex !== -1) {
    // Find the index of the item being updated
    const removingIndex = items.findIndex((prevItem) => prevItem.id === itemId);

    // Duplicate found - merge items
    return {
      updatedItems: mergeDuplicateItems(
        items,
        removingIndex,
        duplicateIndex,
        currentQuantity
      ),
      wasMerged: true,
      mergedIntoIndex: duplicateIndex,
    };
  }

  // No duplicate - just update the item
  const updatedItems = items.map((prevItem) => {
    if (itemId && prevItem.id === itemId) {
      // Match by ID - update with preserved ID and parentSku
      return {
        ...prevItem,
        ...updatedItem,
        id: itemId,
        // Preserve or set parentSku:
        // - If updatedItem has parentSku, use it
        // - If prevItem has parentSku, keep it
        // - If updatedItem has variantSku but no parentSku, use prevItem.sku as parent
        parentSku: updatedItem.parentSku !== undefined 
          ? updatedItem.parentSku 
          : prevItem.parentSku || (updatedItem.variantSku ? prevItem.sku : undefined),
      };
    } else if (!itemId && prevItem.sku === updatedItem.sku) {
      // Fallback for items without ID (backward compatibility)
      return {
        ...prevItem,
        ...updatedItem,
        // Preserve or set parentSku (same logic as above)
        parentSku: updatedItem.parentSku !== undefined 
          ? updatedItem.parentSku 
          : prevItem.parentSku || (updatedItem.variantSku ? prevItem.sku : undefined),
      };
    }
    return prevItem;
  });

  return {
    updatedItems,
    wasMerged: false,
  };
};
