import { FunctionComponent, useCallback, memo } from 'preact/compat';
import { InputFile } from '@adobe-commerce/elsie/components';
import { CsvFileInputProps } from '@/b2b-quick-order/types/quickOrderCsvUpload.types';
import '@/b2b-quick-order/components/CsvFileInput/CsvFileInput.css';

const CsvFileInputComponent: FunctionComponent<CsvFileInputProps> = ({
  t,
  onFileUpload,
  error,
  fileName,
  onDownloadSample,
  showSampleDownload,
  disabled,
}) => {
  const handleFileChange = useCallback(
    (e: Event) => {
      const target = e.target as HTMLInputElement;
      const file = target.files?.[0];
      if (file) {
        onFileUpload(file);
      }
    },
    [onFileUpload]
  );

  const inputClassName = 'b2b-quick-order-csv-file-input__input';

  return (
    <div className="b2b-quick-order-csv-file-input">
      <div className="b2b-quick-order-csv-file-input__title">{t.title}</div>

      <div className="b2b-quick-order-csv-file-input__helper">
        {t.helperText}
        {showSampleDownload && (
          <>
            <button
              type="button"
              className="b2b-quick-order-csv-file-input__download-link"
              onClick={onDownloadSample}
              data-testid="download-sample"
              disabled={disabled}
            >
              {t.downloadSample}
            </button>
          </>
        )}
      </div>

      <div
        className={`b2b-quick-order-csv-file-input__input-wrapper ${
          disabled
            ? 'b2b-quick-order-csv-file-input__input-wrapper--disabled'
            : ''
        }`}
      >
        <InputFile
          id={'quick-order-csv-file-input'}
          label={t.inputLabel}
          className={inputClassName}
          onChange={handleFileChange}
          accept={'.csv'}
          disabled={disabled}
        />
      </div>

      {fileName && (
        <div
          className="b2b-quick-order-csv-file-input__file-name"
          data-testid="file-name"
        >
          {t.selectedFile}: {fileName}
        </div>
      )}

      {error && (
        <div
          className="b2b-quick-order-csv-file-input__error"
          data-testid="error-message"
          role="alert"
        >
          {error}
        </div>
      )}
    </div>
  );
};

export const CsvFileInput = memo(CsvFileInputComponent);
