import { useCallback, useState } from 'preact/hooks';
import {
  UseQuickOrderCsvUploadProps,
  UseQuickOrderCsvUploadReturn,
} from '@/b2b-quick-order/types/quickOrderCsvUpload.types';
import { events } from '@adobe-commerce/event-bus';
import { useText } from '@adobe-commerce/elsie/i18n';
import { validateCsvContent } from '@/b2b-quick-order/lib';

export const useQuickOrderCsvUpload = ({
  routeSampleCSV,
  onFileUpload,
}: UseQuickOrderCsvUploadProps): UseQuickOrderCsvUploadReturn => {
  const [error, setError] = useState<string | null>(null);
  const [fileName, setFileName] = useState<string | null>(null);

  const t = useText({
    invalidFile: 'QuickOrder.CsvFileInput.uploadCSVErrors.invalidFile',
    emptyFile: 'QuickOrder.CsvFileInput.uploadCSVErrors.emptyFile',
    missingColumns: 'QuickOrder.CsvFileInput.uploadCSVErrors.missingColumns',
    extraColumns: 'QuickOrder.CsvFileInput.uploadCSVErrors.extraColumns',
    maxRowsExceeded: 'QuickOrder.CsvFileInput.uploadCSVErrors.maxRowsExceeded',
    skuRequired: 'QuickOrder.CsvFileInput.uploadCSVErrors.skuRequired',
    invalidQuantity: 'QuickOrder.CsvFileInput.uploadCSVErrors.invalidQuantity',
    noValidData: 'QuickOrder.CsvFileInput.uploadCSVErrors.noValidData',
    onlyCSV: 'QuickOrder.CsvFileInput.uploadCSVErrors.onlyCSV',
    failedToRead: 'QuickOrder.CsvFileInput.uploadCSVErrors.failedToRead',
    failedToParse: 'QuickOrder.CsvFileInput.uploadCSVErrors.failedToParse',
  });

  const handleFileUpload = useCallback(
    (file: File) => {
      setError(null);
      setFileName(file.name);

      if (!file.name.toLowerCase().endsWith('.csv')) {
        setError(t.onlyCSV);
        return;
      }

      const reader = new FileReader();

      reader.onload = (e) => {
        try {
          const content = e.target?.result as string;
          const validation = validateCsvContent(content, {
            emptyFile: t.emptyFile,
            missingColumns: t.missingColumns,
            extraColumns: t.extraColumns,
            maxRowsExceeded: t.maxRowsExceeded,
            skuRequired: t.skuRequired,
            invalidQuantity: t.invalidQuantity,
            noValidData: t.noValidData,
          });

          if (!validation.isValid) {
            setError(validation.error!);
            return;
          }

          // Success - emit event or call custom callback
          if (onFileUpload) {
            onFileUpload(validation.data!);
          } else {
            events.emit('quick-order/add-items', validation.data!);
          }

          // Reset state after successful upload
          setFileName(null);
          setError(null);
        } catch (err) {
          setError(t.failedToParse);
        }
      };

      reader.onerror = () => {
        setError(t.failedToRead);
      };

      reader.readAsText(file);
    },
    [onFileUpload, t]
  );

  const handleDownloadSample = useCallback(() => {
    if (routeSampleCSV) {
      window.open(routeSampleCSV(), '_blank');
    } else {
      const csvContent = 'SKU,QTY\nSKU123,1\nSKU456,2\nSKU789,3';
      const blob = new Blob([csvContent], { type: 'text/csv' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = 'sample-quick-order.csv';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    }
  }, [routeSampleCSV]);

  return {
    handleFileUpload,
    error,
    fileName,
    handleDownloadSample,
    showSampleDownload: true,
  };
};
