import React, { useCallback, useState, useRef, useEffect } from 'preact/compat';
import { SearchItem } from '@/b2b-quick-order/types/search.types';
import {
  createBlurHandler,
  clearBlurTimeout,
  handleArrowDown,
  handleArrowUp,
  handleEnterKey,
  handleEscapeKey,
  handleHomeKey,
  handleEndKey,
} from '@/b2b-quick-order/lib';

export interface UseSearchOptions<T extends SearchItem> {
  value: string;
  onChange?: (e: any) => void;
  items: T[];
  shouldShowResults?: boolean;
  onItemClick?: (item: T) => void;
}

export interface UseSearchReturn<T extends SearchItem> {
  // State
  activeIndex: number;
  showResults: boolean;
  showEmptyState: boolean;

  // Refs
  resultsId: React.MutableRefObject<string>;
  inputRef: React.RefObject<HTMLInputElement>;
  itemRefs: React.MutableRefObject<(HTMLDivElement | null)[]>;
  containerRef: React.RefObject<HTMLDivElement>;

  // Handlers
  handleChange: (e: any) => void;
  handleFocus: () => void;
  handleBlur: () => void;
  handleKeyDown: (e: KeyboardEvent) => void;
  createItemClickHandler: (item: T) => () => void;
  getActiveDescendant: () => string | undefined;
}

export const useSearch = <T extends SearchItem = SearchItem>({
  value,
  onChange,
  items,
  shouldShowResults = true,
  onItemClick,
}: UseSearchOptions<T>): UseSearchReturn<T> => {
  const [activeIndex, setActiveIndex] = useState(-1);
  const [initialValue, setInitialValue] = useState('');
  const [itemSelected, setItemSelected] = useState(false);
  const [isClosedManually, setIsClosedManually] = useState(false);

  const resultsId = useRef(
    `search-results-${Math.random().toString(36).substr(2, 9)}`
  );
  const inputRef = useRef<HTMLInputElement>(null);
  const itemRefs = useRef<(HTMLDivElement | null)[]>([]);
  const containerRef = useRef<HTMLDivElement>(null);
  const blurTimeoutRef = useRef<number | null>(null);

  const isOpen = Boolean(value) && !isClosedManually;
  const showResults = shouldShowResults && isOpen && items.length > 0;
  const showEmptyState = shouldShowResults && isOpen && items.length === 0;

  useEffect(() => {
    setActiveIndex(-1);
    // Don't reset isClosedManually here - only reset on focus
    // This prevents results from reopening after Tab
  }, [items]);

  useEffect(() => {
    return () => {
      clearBlurTimeout(blurTimeoutRef.current);
    };
  }, []);

  useEffect(() => {
    // Auto-scroll active item into view when navigating with keyboard
    if (activeIndex >= 0 && itemRefs.current[activeIndex]) {
      const element = itemRefs.current[activeIndex];
      if (element && typeof element.scrollIntoView === 'function') {
        element.scrollIntoView({
          behavior: 'smooth',
          block: 'nearest',
        });
      }
    }
  }, [activeIndex]);

  const handleChange = useCallback(
    (e: any) => {
      // Reset isClosedManually when user types
      if (isClosedManually) {
        setIsClosedManually(false);
      }
      onChange?.(e);
    },
    [onChange, isClosedManually]
  );

  const createItemClickHandler = useCallback(
    (item: T) => () => {
      setItemSelected(true);
      setIsClosedManually(true);
      onItemClick?.(item);
      setActiveIndex(-1);
    },
    [onItemClick]
  );

  const handleFocus = useCallback(() => {
    clearBlurTimeout(blurTimeoutRef.current);
    blurTimeoutRef.current = null;
    setInitialValue(value || '');
    setItemSelected(false);
    setIsClosedManually(false);
  }, [value]);

  const handleBlur = useCallback(() => {
    blurTimeoutRef.current = createBlurHandler({
      containerRef: containerRef.current,
      itemSelected,
      initialValue,
      currentValue: value || '',
      onValueRestore: (restoredValue) => {
        onChange?.({ target: { value: restoredValue } } as any);
      },
      onClose: () => {
        setIsClosedManually(true);
      },
    });
  }, [itemSelected, initialValue, value, onChange]);

  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (!showResults) return;

      switch (e.key) {
        case 'ArrowDown':
          e.preventDefault();
          setActiveIndex((prev) => handleArrowDown(prev, items.length));
          break;
        case 'ArrowUp':
          e.preventDefault();
          setActiveIndex((prev) => handleArrowUp(prev));
          break;
        case 'Home':
          if (showResults && items.length > 0) {
            e.preventDefault();
            setActiveIndex(handleHomeKey());
          }
          break;
        case 'End':
          if (showResults && items.length > 0) {
            e.preventDefault();
            setActiveIndex(handleEndKey(items.length));
          }
          break;
        case 'Tab':
          clearBlurTimeout(blurTimeoutRef.current);
          blurTimeoutRef.current = null;
          setIsClosedManually(true);
          onChange?.({ target: { value: initialValue } } as any);
          break;
        case 'Enter': {
          const wasHandled = handleEnterKey(activeIndex, items, (item) => {
            setItemSelected(true);
            setIsClosedManually(true);
            onItemClick?.(item);
            setActiveIndex(-1);
          });
          if (wasHandled) {
            e.preventDefault();
          }
          break;
        }
        case 'Escape':
          e.preventDefault();
          handleEscapeKey(
            initialValue,
            inputRef.current,
            (restoredValue) => {
              onChange?.({ target: { value: restoredValue } } as any);
              setActiveIndex(-1);
              setIsClosedManually(true);
            },
            () => {
              setIsClosedManually(true);
            }
          );
          break;
      }
    },
    [showResults, items, activeIndex, onItemClick, onChange, initialValue]
  );

  const getActiveDescendant = useCallback(() => {
    if (activeIndex >= 0 && showResults) {
      return `${resultsId.current}-item-${activeIndex}`;
    }
    return undefined;
  }, [activeIndex, showResults]);

  return {
    activeIndex,
    showResults,
    showEmptyState,
    resultsId,
    inputRef,
    itemRefs,
    containerRef,
    handleChange,
    handleFocus,
    handleBlur,
    handleKeyDown,
    createItemClickHandler,
    getActiveDescendant,
  };
};
