import { memo } from 'preact/compat';
import { Input } from '@adobe-commerce/elsie/components';
import { classes } from '@adobe-commerce/elsie/lib/classes';
import { SearchProps, SearchItem } from '@/b2b-quick-order/types/search.types';
import { useSearch } from '@/b2b-quick-order/hooks/useSearch';
import '@/b2b-quick-order/components/Search/Search.css';
import { Slot } from '@adobe-commerce/elsie/lib';

const cursorStyle = { cursor: 'pointer' as const };
const defaultCursorStyle = { cursor: 'default' as const };

const SearchComponent = <T extends SearchItem = SearchItem>({
  t,
  value,
  onChange,
  items,
  shouldShowResults = true,
  className,
  onItemClick,
  slots,
}: SearchProps<T>) => {
  const {
    activeIndex,
    showResults,
    showEmptyState,
    resultsId,
    inputRef,
    itemRefs,
    containerRef,
    handleChange,
    handleFocus,
    handleBlur,
    handleKeyDown,
    createItemClickHandler,
    getActiveDescendant,
  } = useSearch({
    value,
    onChange,
    items,
    shouldShowResults,
    onItemClick,
  });

  return (
    <div
      ref={containerRef}
      className={classes(['b2b-quick-order-search', className])}
    >
      <Input
        ref={inputRef}
        className="b2b-quick-order-search__input"
        value={value}
        onChange={handleChange}
        onFocus={handleFocus}
        onBlur={handleBlur}
        placeholder={t.searchPlaceholder}
        aria-label={t.searchAriaLabel}
        role="combobox"
        aria-autocomplete="list"
        aria-expanded={showResults}
        aria-controls={resultsId.current}
        aria-activedescendant={getActiveDescendant()}
        onKeyDown={handleKeyDown}
      />

      {showResults && (
        <div
          id={resultsId.current}
          role="listbox"
          className="b2b-quick-order-search__results"
          aria-label={t.searchAriaLabel}
        >
          {items.map((item, index) => (
            <Slot
              key={item.sku}
              slot={slots?.QuickOrderSearchAutocompleteItem}
              name={'QuickOrderSearchAutocompleteItem'}
              context={{
                item,
                index,
                createItemClickHandler,
                activeIndex,
              }}
            >
              <div
                id={`${resultsId.current}-item-${index}`}
                ref={(el) => (itemRefs.current[index] = el)}
                role="option"
                aria-selected={index === activeIndex}
                className={classes([
                  'b2b-quick-order-search__result-item',
                  index === activeIndex &&
                    'b2b-quick-order-search__result-item--active',
                ])}
                onClick={createItemClickHandler(item)}
                style={onItemClick ? cursorStyle : defaultCursorStyle}
              >
                {`${item.sku} ${item.name}`}
              </div>
            </Slot>
          ))}
        </div>
      )}

      {showEmptyState && (
        <div
          className="b2b-quick-order-search__empty-state"
          role="status"
          aria-live="polite"
        >
          {t.searchEmptyState}
        </div>
      )}

      {showResults && (
        <div
          className="sr-only"
          role="status"
          aria-live="polite"
          aria-atomic="true"
        >
          {items.length}{' '}
          {items.length === 1 ? t.resultAvailable : t.resultsAvailable}.{' '}
          {t.srInstructions}
        </div>
      )}
    </div>
  );
};

export const Search = memo(SearchComponent) as typeof SearchComponent;
