import { FunctionComponent, memo } from 'preact/compat';
import { Button } from '@adobe-commerce/elsie/components';
import { classes } from '@adobe-commerce/elsie/lib/classes';
import { QuickOrderVariantsActionsProps } from '@/b2b-quick-order/types';
import { Slot } from '@adobe-commerce/elsie/lib';
import '@/b2b-quick-order/components/QuickOrderVariantsActions/QuickOrderVariantsActions.css';

const QuickOrderVariantsActionsComponent: FunctionComponent<
  QuickOrderVariantsActionsProps
> = ({
  t,
  onClear,
  onSaveToCsv,
  onCollectData,
  isDisabled = false,
  variantsCount = 0,
  className,
  slots,
}) => {
  return (
    <div
      className={classes(['b2b-quick-order-variants-actions', className])}
      data-testid="variants-actions"
    >
      <Slot
        name="Actions"
        slot={slots?.Actions}
        context={{
          onClear,
          onSaveToCsv,
          onCollectData: onCollectData || (() => []),
          isDisabled,
          variantsCount,
        }}
      >
        <div className="b2b-quick-order-variants-actions__buttons">
          <Button
            variant="secondary"
            size="medium"
            onClick={onClear}
            disabled={isDisabled || variantsCount === 0}
            aria-label={t.clearButton}
            data-testid="variants-clear-button"
          >
            {t.clearButton}
          </Button>
          <Button
            variant="primary"
            size="medium"
            onClick={onSaveToCsv}
            disabled={isDisabled || variantsCount === 0}
            aria-label={t.saveToCsvButton}
            data-testid="variants-save-csv-button"
          >
            {t.saveToCsvButton}
          </Button>
        </div>
      </Slot>
    </div>
  );
};

export const QuickOrderVariantsActions = memo(
  QuickOrderVariantsActionsComponent
);
