import { OrderItem } from '@/b2b-quick-order/types';

/**
 * Check if an item is valid for adding to cart
 * @param item - The order item to validate
 * @returns true if item is invalid (should stay in notification), false if valid
 */
export const isItemInvalid = (item: OrderItem): boolean => {
  const hasBasicIssues = !item.inStock || !item.addToCartAllowed;

  if (item.options && item.options.length > 0) {
    // Options must be loaded before validation
    const optionsNotReady = item.options.some(
      (opt) => !opt.items || opt.items.length === 0
    );

    if (optionsNotReady) {
      return true;
    }

    const hasRequiredOptions = item.options.some((opt) => opt.required);

    if (hasRequiredOptions) {
      // Required options: all must be selected
      const allRequiredSelected = item.options.every((opt) => {
        if (!opt.required) return true;
        return opt.items?.some((optItem) => optItem.selected);
      });
      return hasBasicIssues || !allRequiredSelected;
    }

    // Optional options: at least one must be selected
    const hasSelectedOption = item.options.some(
      (option) =>
        option.items &&
        option.items.length > 0 &&
        option.items.some((optionItem) => optionItem.selected === true)
    );
    return hasBasicIssues || !hasSelectedOption;
  }

  return hasBasicIssues;
};
